function cn(...classes: Array<string | false | null | undefined>) {
  return classes.filter(Boolean).join(" ");
}

function StatusChip({ label, tone = "neutral" }: { label: string; tone?: Tone }) {
  return (
    <span className={cn("inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-bold", toneClasses[tone].chip)}>
      <span className={cn("h-2 w-2 rounded-full", toneClasses[tone].dot)} />
      {label}
    </span>
  );
}

function ProgressBar({ value, tone = "info" }: { value: number; tone?: Tone }) {
  return (
    <div className="h-2 rounded-full bg-[#E2E8F0] overflow-hidden mt-2">
      <div className={cn("h-full rounded-full transition-all duration-500", toneClasses[tone].dot)} style={{ width: `${Math.max(0, Math.min(100, value))}%` }} />
    </div>
  );
}

